/// <summary>
/// Demonstrates creating a sales order and assigning it to DMF staging records.
/// </summary>
class OMGTutorialMessageProcessorDMF extends OMGMessageProcessorDMF
{
    }

Method.Source:
public void preTargetProcessing(DMFDefinitionGroupName      _definitionGroupName,
                                DMFExecutionId              _executionId,
                                DMFEntityName               _entityName,
                                OMGInboundMessageTable      _inboundMessage)
{
    // Create a new sales order, and populate SalesId on Staging table
    SalesTable      salesTable;
    CustTable       custTable = CustTable::find('004003');
    NumberSeq       numberSeq;

    ttsbegin;

    salesTable.clear();
    salesTable.initValue();

    numberSeq = NumberSeq::newGetNum(SalesParameters::numRefSalesId());
    numberSeq.used();

    salesTable.SalesId          = numberSeq.num();
    salesTable.CustAccount      = custTable.AccountNum;
    salesTable.initFromCustTable();

    salesTable.InventSiteId = custTable.InventSiteId;
    salesTable.InventLocationId = custTable.InventLocation;

    salesTable.insert();

    // --------
    SalesOrderLineV2Staging     salesOrderLineV2Staging;

    while select forupdate salesOrderLineV2Staging
        where salesOrderLineV2Staging.DefinitionGroup   == _definitionGroupName   &&
              salesOrderLineV2Staging.ExecutionId       == _executionId
    {
        salesOrderLineV2Staging.SalesOrderNumber = salesTable.SalesId;
        salesOrderLineV2Staging.update();
    }

    ttscommit;
}

/// <summary>
/// Invokes the base post-processing hook after importing the entity records.
/// </summary>
/// <param name = "_definitionGroupName">The DMF definition group.</param>
/// <param name = "_executionId">The import execution ID.</param>
/// <param name = "_entityName">The imported entity name.</param>
/// <param name = "_inboundMessage">The inbound message being processed.</param>
public void postTargetProcessing(DMFDefinitionGroupName _definitionGroupName, DMFExecutionId _executionId, DMFEntityName _entityName, OMGInboundMessageTable _inboundMessage)
{
    super(_definitionGroupName, _executionId, _entityName, _inboundMessage);
}

/// <summary>
/// Imports an inbound message through the base DMF processor.
/// </summary>
/// <param name = "_inboundMessage">The message containing the import data.</param>
/// <returns>The DMF import status and response details.</returns>
public OMGInboundMessageResponseContract processMessage(OMGInboundMessageTable _inboundMessage)
{
    OMGInboundMessageResponseContract ret;

    ret = super(_inboundMessage);

    return ret;
}

/// <summary>
/// Transfers the entity staging records to their target tables through DMF.
/// </summary>
/// <param name = "_definitionGroupName">The DMF definition group.</param>
/// <param name = "_executionId">The import execution ID.</param>
/// <param name = "_entityName">The entity to transfer to the target.</param>
/// <param name = "_inboundMessage">The inbound message being processed.</param>
public void processToTarget(DMFDefinitionGroupName _definitionGroupName, DMFExecutionId _executionId, DMFEntityName _entityName, OMGInboundMessageTable _inboundMessage)
{
    super(_definitionGroupName, _executionId, _entityName, _inboundMessage);
}
